-- Final booking charge is the report source, as instructed on 9 October 2026.
-- Only complete approval records with reviewed pricing-input hashes are eligible.
-- Staff-added visitors remain in the source list. Payment images and old corrections are preserved.
-- Deployment verifies every source hash before applying this atomic migration.
CREATE TABLE booking_charge_corrections (
 ref TEXT PRIMARY KEY, visitDateISO TEXT NOT NULL, fromTotal INTEGER NOT NULL, bookingTotal INTEGER NOT NULL,
 expectedVersion INTEGER NOT NULL, pricingSha256 TEXT NOT NULL, fromCounters TEXT NOT NULL, toCounters TEXT NOT NULL,
 appliedAt TEXT NOT NULL DEFAULT ''
);

CREATE TABLE booking_charge_guard (valid INTEGER CHECK(valid = 1));
SELECT 0 FROM reservations_archive r JOIN booking_charge_corrections c ON r.ref = c.ref
LEFT JOIN reservation_payment_locks l ON l.ref = r.ref
WHERE r.visitDateISO != c.visitDateISO OR r.version != c.expectedVersion OR r.total != c.fromTotal
 OR r.status NOT IN ('ชำระแล้ว','เสร็จสิ้น') OR l.total IS NULL OR l.total != c.fromTotal
 OR r.visitorCount != json_extract(c.fromCounters,'$.visitorCount')
 OR r.adultCount != json_extract(c.fromCounters,'$.adultCount')
 OR r.child5to8Count != json_extract(c.fromCounters,'$.child5to8Count')
 OR r.childUnder5Count != json_extract(c.fromCounters,'$.childUnder5Count');
DROP TABLE booking_charge_guard;
SELECT strftime('%Y-%m-%d %H:%M:%S','now','+7 hours'),'system','booking_charge_reconciled',r.ref,
 json_object('from',r.total,'to',c.bookingTotal,'visitDateISO',r.visitDateISO,
 'pricingSha256',c.pricingSha256,'fromCounters',json(c.fromCounters),'toCounters',json(c.toCounters),
 'source','final reservation and recorded visitor approvals','via','migration 0025'),'success'
FROM reservations_archive r JOIN booking_charge_corrections c ON r.ref=c.ref;
UPDATE booking_charge_corrections SET appliedAt=strftime('%Y-%m-%dT%H:%M:%fZ','now')
WHERE ref IN (SELECT ref FROM reservations_archive);
UPDATE reservation_payment_locks
SET total=(SELECT bookingTotal FROM booking_charge_corrections c WHERE c.ref=reservation_payment_locks.ref)
WHERE ref IN (SELECT ref FROM booking_charge_corrections WHERE appliedAt!='');
UPDATE reservations_archive
SET total=(SELECT bookingTotal FROM booking_charge_corrections c WHERE c.ref=reservations_archive.ref),
 visitorCount=(SELECT json_extract(toCounters,'$.visitorCount') FROM booking_charge_corrections c WHERE c.ref=reservations_archive.ref),
 adultCount=(SELECT json_extract(toCounters,'$.adultCount') FROM booking_charge_corrections c WHERE c.ref=reservations_archive.ref),
 child5to8Count=(SELECT json_extract(toCounters,'$.child5to8Count') FROM booking_charge_corrections c WHERE c.ref=reservations_archive.ref),
 childUnder5Count=(SELECT json_extract(toCounters,'$.childUnder5Count') FROM booking_charge_corrections c WHERE c.ref=reservations_archive.ref),
 version=version+1, updatedAt=strftime('%Y-%m-%dT%H:%M:%fZ','now')
WHERE ref IN (SELECT ref FROM booking_charge_corrections WHERE appliedAt!='');
DELETE FROM d1_cache WHERE key NOT LIKE 'rl:%';
UPDATE settings SET value=CAST(CAST(value AS INTEGER)+1 AS TEXT)
WHERE key IN ('data_version','data_version:reservations');
